+/// Sample extra tangency points along shallow Z-sloped edges where the XY
+/// ellipse chord between adjacent angles of `ds` would exceed `MAX_CHORD`.
+fn push_shallow_edge_supports(
+    v: &[Point3; 3],
+    cz: f64,
+    r: f64,
+    dtheta_ds: f64,
+    dtheta_max: f64,
+    pts: &mut Vec<Point2>,
