+        let (dx, dy) = (q1.x - q0.x, q1.y - q0.y);
+        let l_xy = dx.hypot(dy);
+        if ez == 0.0 || l_xy <= 1e-9 || ez.abs() >= l_xy {
+            continue;
+        }
+        let z_lo = q0.z.min(q1.z).max(cz - r);
+        let z_hi = q0.z.max(q1.z).min(cz + r);
+        if z_lo >= z_hi {
