+fn simulate_and_gouge(
+    facets: &[Triangle],
+    path: &Toolpath,
+    box_min: (f64, f64),
+    box_max: (f64, f64),
+    stock_top: f64,
+) -> (usize, f64) {
+    let mut stock = Stock::block(
+        Backend::Column,
+        box_min.0,
+        box_min.1,
+        box_max.0,
+        box_max.1,
+        stock_top,
+        0.08,
+    )
+    .expect("test stock");
+    let sim = SimOp {
+        moves: &path.moves,
+        radius: R,
+        ball: true,
+        cone: None,
+        corner: None,
+    };
+    stock.simulate(&[sim]).expect("simulate");
+    let dev = stock.deviate(facets, DEV_TOL).expect("deviate");
+    (dev.gouge_cells, dev.max_gouge)
+}
